PAGES=[]
def page(title,kicker,lead,sections,**extra):
    PAGES.append(dict(title=title,kicker=kicker,lead=lead,sections=[{'title':t,'text':v} for t,v in sections],**extra))

page('A place worth returning to','THE PRESENT-DAY WORLD','The Burrow is a shared home before it becomes the setting of an adventure.',[
 ('One town, several ways of living','Outdoor terraces hold markets, gardens and homes. Two underground levels hold permanent neighborhoods, schools, shops and shared meals. Residents move between them for work, friendship and leisure. Neither part is a lesser home.'),
 ('What this edition fixes','Every existing footprint, route, level and crossing is retained. Seven detailed sub-plans fit inside allocated spaces. Eight recurring residents, neighborhood identities and everyday institutions give those spaces a social life.'),
 ('What the owner has established','Madger created or founded the Burrow. This does not mean he rules it or built every part alone. Why he founded it, the condition of the site beforehand and who joined him remain questions for the history phase.'),
 ('Present fact, history, and possibility','Present-day entries can be used now. History reservations are questions, not hidden answers. Story seeds are possible conflicts, not events that have already happened. Concept art establishes atmosphere; measured plans control placement.')])

page('Five neighborhoods, one community','NEIGHBORHOOD IDENTITIES','Residents have local habits without becoming stereotypes of their address.',[],kind='neighborhoods')

page('The ordinary day has a shape','ROUTINES & MOVEMENT','Time is tracked by the surface day. Underground lighting and quiet periods follow it, while essential services work in shifts.',[
 ('Before breakfast','Receiving teams count goods. Kitchen shifts prepare bread and meals. Maintenance teams compare local readings. Early deliveries stay on work routes and avoid sleeping galleries.'),
 ('Morning','Families leave homes above and below. Children and guardians travel toward UG-06; adults go to gardens, shops and workshops. Visitors enter through the public arrival sequence. Nobody must pass through a private home to reach a civic place.'),
 ('Midday','The surface market and Underhall share the busiest exchanges. Shared kitchens supplement household kitchens. Tables make room for people who are eating alone as well as established groups.'),
 ('Afternoon','Learning clubs, repairs and personal errands overlap. Service staff hand over unfinished tasks. School is not the only place children appear, and work is not the only activity adults have.'),
 ('Evening','People return to different neighborhoods, cook, rehearse, read and visit. The outdoor gate can close routinely after an announced last entry; underground inner gates stay open unless a protective state is explicitly declared.'),
 ('Night','Quiet does not mean abandoned. Limited service shifts continue, routes remain legible and home privacy matters. Night staff take rest later; daylight characters cannot appear everywhere without time passing.')])

page('How the community makes decisions','CIVIC LIFE','Madger brings people together. The town also works when he is absent, tired or wrong.',[
 ('The Common Table','Residents raise matters at BRW-02 or scheduled UG-14 assemblies. Neighborhood stewards and service leads explain their part; a rotating facilitator keeps the discussion usable. Decisions and reasons are recorded where residents can inspect them.'),
 ('Ordinary rights','People can ask questions, correct a record, decline an optional activity and keep their home private. Welcome, basic care and refuge do not depend on a wallet, rank, species or personal friendship with a hero.'),
 ('Work has accountable owners','Service teams own schedules and handoffs. One named person leads a shift, but another can take over. The Records House preserves evidence and corrections; it does not silently become the government.'),
 ('Disagreement without an enemy','A grower, a teacher and a repair team can reasonably want the same cart or timeslot. Show the actual constraint, listen to affected people and record the compromise. A losing suggestion does not make its owner disloyal.'),
 ('Urgent decisions','A local lead can respond to immediate danger within an established role. Gate and service changes are logged and reviewed afterward. Urgency is temporary responsibility, not permanent power.'),
 ('The founder\'s place','Madger has influence through trust and action, not a private veto. His developing leadership is visible when he accepts a good objection and helps someone else carry a decision through.')])

page('Work, exchange and finite resources','THE PRACTICAL WORLD','The town is prosperous because useful work is shared, maintained and recorded.',[
 ('A household economy','Residents exchange goods and paid work, share some resources and volunteer by choice. Use ordinary prices, tickets and receipts when a scene needs them. Currency names, exchange rates and any relationship to real-world MADGER products remain unassigned.'),
 ('Food takes several routes','Surface gardens and powered grow rooms supply part of the food. Trade brings grain and other staples; stores buffer interruptions. Household cooking and common kitchens coexist. The Bread Counter receives prepared batches from UG-12 rather than adding an unplanned oven shaft.'),
 ('Repair has a queue','A repair ticket records item, owner, fault, promised next update and current status. Loan tools have a return record. A delay can be honest; hiding it creates a relationship problem before it becomes a safety problem.'),
 ('Shared resources need boundaries','Communal does not mean ownerless. A household\'s keepsake is not quest loot. Lending a cart needs consent and a return time. Essential service stock is separate from a decorative project budget.'),
 ('Local consequences first','A missing flour crate affects named orders and a meal plan. A failed grow light affects a room and its crop schedule. State the reserve and the alternative before escalating to a town-wide crisis.'),
 ('Rest is part of capacity','Staff rotations, apprentices and handoffs are visible. Gorilla cannot lift every object, Bot cannot inspect every log and Edda cannot remain on duty forever. Ordinary neighbors keep things running.')])

page('Culture you can see and hear','MATERIALS, CUSTOMS & BELONGING','The Burrow feels like one place through recurring details, not identical buildings or identical residents.',[
 ('A repair is allowed to show','A neat seam, a replaced chair rung and a dated bridge repair can be visible. Makers receive credit. This supports pride in care without implying an ancient tradition or founding legend that has not been written.'),
 ('Courtesy at a threshold','Knock, wait and ask before entering. Leave the common street clear. Return borrowed objects to the agreed place. Visitors can learn these habits through a friendly interaction instead of a lecture.'),
 ('Meals and celebrations','Shared tables welcome newcomers; participation is optional. Bridge Reopening Day is a specific present event, not yet an annual founding festival. Small performances, games and skill exchanges need no catastrophe to justify an episode.'),
 ('Readable places','Combine area number, word and simple symbol. Color helps but is never the only direction cue. Workshop tools are labeled; school notices use pictures; light levels change gently along public routes.'),
 ('A controlled sound palette','Surface scenes carry wind, water, wheel movement and market calls. Underground scenes carry close footsteps, tableware, soft mechanical ventilation and household sounds. No constant ominous drone under a happy town.'),
 ('People and animals','This edition adds person-like animal residents without changing Snow\'s identity as an ordinary adult dog. Final population biology and species histories remain open. Appearance does not determine honesty, intelligence or allegiance.')])

page('Neighbors with work of their own','RECURRING RESIDENTS / 01','Present-day roles are authored additions. Birthplaces, arrival stories, ages in years and family histories remain open.',[],kind='residents',resident_ids=['RES-01','RES-02','RES-03','RES-04'])
page('Neighbors beyond the heroes','RECURRING RESIDENTS / 02','These residents can disagree, be funny, make errors and change without every story making them a villain or victim.',[],kind='residents',resident_ids=['RES-05','RES-06','RES-07','RES-08'])

page('Four heroes in a larger town','RELATIONSHIPS & CHARACTER PRESSURE','The existing hero arcs stay intact. Their growth appears through choices that affect other people.',[
 ('Madger / belonging without control','He starts things and makes introductions. Mara reflects his habit of saying yes to too much; Pell shows how welcome can work through an ordinary system. Progress means entrusting a meaningful task, accepting a refusal and sharing credit.'),
 ('Gorilla White / strength that teaches','The workshop is shared. Tavi needs a chance to finish a job, and Edda expects Gorilla to rest when necessary. Progress means demonstrating a skill, letting someone else try and receiving protection without shame.'),
 ('MADGER Bot / usefulness without certainty','Iona compares physical readings; Pell sees the person behind a record. Bot can preserve conflicting evidence without inventing an answer. Progress means marking uncertainty clearly and explaining the limits of his access.'),
 ('Snow White / attention that connects','Her actions are canine: sniffing, listening, pausing, looking back, returning and resting. Neri and the children learn to wait for a clear indication. Snow never translates a scent into a spoken explanation or detects a digital packet.'),
 ('Friendship has reciprocal care','A tired friend receives help. A disagreement is resolved by changed conduct, not merely a speech. The team shares ordinary meals and jokes so later separation or danger has an established emotional cost.'),
 ('Not every hero in every scene','Episodes can focus on one or two relationships while preserving the others\' whereabouts. The pilot still includes all four; its brief runtime does not require introductions for all eight new residents.')])

page('Underhall is a real address','REPEATABLE STORY LOCATION','Four named north-side shops now occupy existing bays. Their customers and deliveries share the public square; no exterior wall or main corridor moves.',[],kind='underhall')

for sub in SUBPLANS:
 page(sub['name'],'DETAILED SUB-PLAN / '+sub['id'],sub['purpose'],[],kind='plan',plan_id=sub['id'])

page('Safety is a condition, not a color','SAFE PLACES & LOCAL RISK','A place can be welcoming, private, supervised or temporarily unsafe. Keep access rules separate from threat level.',[
 ('Everyday civic spaces','Markets, commons, school routes, clinic waiting areas and the assembly hall are maintained safe in the peaceful baseline. Minor friction is social or practical; the background does not randomly attack residents.'),
 ('Private spaces','Homes and personal records are private, not dangerous. A closed bedroom door is a boundary, not automatic evidence of a secret. Ask who has permission and why.'),
 ('Working spaces','A running wheel, hot kitchen, tool bench, wet floor or service plant can present an ordinary local hazard. Supervision and a clear work boundary make the risk understandable without making the whole district sinister.'),
 ('Temporary restricted areas','Inspection, repair, smoke or a blocked route can change one location\'s status. Record start, reason, affected paths, alternate route and conditions for reopening. Restore or preserve damage explicitly.'),
 ('Surface overrun','The welcome sequence, inner closures, service boundary and stair thresholds keep their v2 roles. The town\'s response is protection of people and lifelines. No extra escape tunnel appears simply because a scene needs one.'),
 ('Dangerous regions come later','No named wilderness, monster territory, hostile settlement or attacker base is established here. Those places will need their own geography, ecology, history, inhabitants and connection to the Burrow before use.')])

page('Lifelines and trust','SYSTEMS THAT SUPPORT STORIES','Separate physical events, digital records and what characters believe happened.',[
 ('Water and air','Iona\'s team checks local conditions; records help compare them. Drinking water stays separate from the canal. Underground waste is pumped up to the established service connection. Doors do not make air, pumps or staff unnecessary.'),
 ('Power and food','Local supplies and backups have limited capacity. The wheel, roofs and batteries are not one omnipotent core. Grow rooms need power. Food reserves require quantities and elapsed time before a shortage becomes a plot fact.'),
 ('A receipt is a claim','D17 remains a delivery identifier. A duplicate could reflect error, replay, fraud or another cause not yet established. The pilot does not decide which. Bot preserves source, time and uncertainty rather than accusing a visitor.'),
 ('Physical controls remain physical','A forged status cannot move a manual gate bar. A later antagonist must have a documented route, ability, access and limit. Do not replace a mystery with a universal hacking power.'),
 ('Private information has purpose','A service reading, a delivery record and a care record have different viewers. Residents can request corrections. No omniscient surveillance wall is added to simplify exposition.'),
 ('Repair creates history','When a later event changes a sign, door, service setting or relationship, record its before and after. The next episode inherits that result instead of resetting the town for convenience.')])

page('Many kinds of episode can live here','REPEATABLE STORY POSSIBILITIES','These are story seeds, not completed events or locked episode orders.',[
 ('Community comedy / a favor too many','Mara promises more orders than one shift can finish. Madger\'s attempt to help creates a second commitment. A truthful renegotiation lets others plan; the cost is awkwardness and work, not a surprise villain.'),
 ('Craft / the unfinished chair','Tavi wants a visible success. A repair looks finished but still fails an ordinary check. He must label it honestly and ask for help before a neighbor uses it.'),
 ('Learning / the map that misleads','Neri\'s group tests a wayfinding card. Jun discovers it depends on color and an adult\'s reading height. A clearer sign helps visitors and changes Neri\'s planned lesson.'),
 ('Friendship / the empty place at supper','Gorilla misses a shared meal because everyone assumes he can finish one more job. The others must notice the habit, not just deliver a plate. He must also name his own limit.'),
 ('Mystery / two records, one crate','A delivery count disagrees with a stored receipt. Bot and Pell separate what is known from what is guessed. A local discrepancy supports investigation without deciding the season villain in advance.'),
 ('Weather, care and defense later','A seasonal disruption can require a route change; a recovery story can test patience; an eventual defense story can test welcome under pressure. Each uses known places, bounded abilities and lasting consequences.')])

page('The pilot still begins with joy','EPISODE 1 / FIVE MINUTES','The audience should care about ordinary life before it notices the first discrepancy.',[
 ('00:00-00:50 / home, street, sunlight','Begin in an underground household and Underhall. Follow ordinary movement up to the surface. All four heroes contribute through brief useful actions. Do not open on alarms, fortifications or a lore monologue.'),
 ('00:50-01:40 / a welcome','A visitor and delivery show public access. Inner gates stand open. One duplicate D17 receipt is quietly preserved. Use inward framing at the outdoor threshold so exterior geography stays unassigned.'),
 ('01:40-03:00 / shared accomplishment','Neighbors reopen the weather-repaired bridge. Gorilla accepts help; Madger shares credit. The bridge remains sound. Allow real route changes and time cuts between locations.'),
 ('03:00-04:10 / life continues','Learning, food and a small personal exchange keep the town alive. After a time cut, Snow holds an indication at the intact gate relay. This is a physical trace with no known cause.'),
 ('04:10-05:00 / homeward, then a question','Friends and households return home. Establish routine evening gate closing before the final unexplained acknowledgment. No one has passed. End with a small contradiction, not an attacker reveal.'),
 ('What the new cast contributes','One or two recurring residents may have readable supporting actions; others remain background or offscreen. Avoid using five minutes to explain eight biographies. Their deeper stories belong in later episodes.')])

page('Build history from evidence and choices','THE NEXT PHASE / RESERVED DOSSIERS','The present world is now detailed enough to ask specific historical questions without filling the answers prematurely.',[
 ('Madger and the founding','Owner-established fact: Madger created the Burrow. Still open: what he wanted to protect or provide, what existed at the site, the first commitment he made, who disagreed, what he sacrificed and how shared responsibility grew.'),
 ('The four companions','For each pair: where they first met, what each wanted, the initial misunderstanding, the action that earned trust and the unresolved difference that survives today. Establish order and elapsed time before writing flashbacks.'),
 ('The residents\' origins','Track former home, reason for leaving or staying, skills brought, people left behind, arrival route and present sense of belonging. Not every resident must be a refugee or share one founding trauma.'),
 ('Every place has a material history','For each area: prior condition, builder or community, purpose at creation, source of materials, later alterations and surviving evidence. Do not date a door, trophy or inscription until its event is recorded.'),
 ('What is true versus remembered','Maintain objective event, eyewitness accounts, rumor and character belief separately. A mistaken memory can be dramatic; it must not silently alter the factual ledger.'),
 ('Chronology before flashbacks','Use relative sequence IDs until calendar and character ages are fixed. Give an event prerequisites, location, participants, result and who knows. Then connect it to the already established present.')])

page('Make future threats belong to this world','ANTAGONISTS, CREATURES & DANGEROUS PLACES','Villains, monsters and hostile animals will be developed in the history and wider-world phase, with reasons, limits and consequences.',[
 ('An antagonist is more than an attack','Reserve fields for desire, belief, grievance, chosen methods, resources, limits, relationships and a line they will or will not cross. Explain what they want from the Burrow and why they cannot simply take it.'),
 ('Species is not allegiance','An evil animal can be an individual who makes cruel choices. A dangerous predator can act through hunger or territory. Keep moral choice, ecological danger and any later supernatural influence distinct.'),
 ('A creature belongs somewhere','Define habitat, food, movement, senses, reproduction if relevant, signs of presence and interaction with other life. Establish what residents know before an encounter. Powers need visible limits and costs.'),
 ('Safe and dangerous are contextual','A home refuge can be safe for residents; a nesting area can be dangerous to an intruder without being evil. Map boundaries and routes. A monster does not appear in a neighborhood merely because an action scene is due.'),
 ('Mystery is not a premature answer','No villain identity, monster species, magical system or exterior map is fixed by this edition. The D17 record and Snow\'s trace remain unresolved; neither is retroactively declared proof of a creature or faction.'),
 ('Reveal in stages','A later story may progress from observation to competing explanations, a verified local effect, a responsible actor and wider stakes. Each revelation must explain prior evidence and leave the characters with a meaningful choice.')])

page('A world that can carry seasons','STORY CONTINUITY & PRODUCTION','A season should change relationships and knowledge while preserving a recognizable home.',[
 ('Choose one central question','Examples for future development: Can a welcoming community protect itself without losing trust? When does helping become control? What does belonging require from a founder and from a newcomer? These are possibilities, not a locked season plan.'),
 ('Give each episode a complete local story','A person wants something in a specific place. A real constraint forces a choice. That choice has a visible cost or benefit. The episode resolves its local question while leaving a consequence another story can use.'),
 ('Track parallel arcs','For each hero record present belief, test, choice, changed behavior and relationship effect. Use small differences across episodes. A speech without a changed action is not an earned arc.'),
 ('Limit exposition','Let recurring signs, places and habits carry familiarity. Introduce an origin detail only when it affects a current decision. A history volume can be extensive while an episode reveals only what that moment needs.'),
 ('Separate story and game states','Player upgrades, collectibles and retries do not become historical facts automatically. The same place keeps its coordinates. An anime background and a game room agree on doors, travel connections and permanent objects.'),
 ('Before a scene is approved','Check location and access state, time and travel, who knows what, resources and injuries, approved likenesses and voices, physical limits, and the event ledger. Snow remains canine. Madger keeps normal teeth and a clean face.')])

page('What is now ready to use','EDITION REGISTER / v2.1.0','This is an additive present-day expansion. It does not move the Burrow or silently write its past.',[
 ('Seven detailed spaces','UG-03-S01 Bread Counter; S02 Repair & Tool Loan; S03 Pantry & Produce; S04 Mending Room; UG-06-R01 Learning Room One; UG-07-R01 Care Room One; UG-04-H001 Lantern Street Home 001. Every footprint stays inside its existing parent allocation.'),
 ('Five neighborhoods and eight neighbors','The original surface neighborhood and four underground wards now have distinct daily identities. Eight resident dossiers record present roles, desires, strengths, flaws and relationships, with historical fields intentionally open.'),
 ('What stays unchanged','All 37 primary area positions and footprints, the surface and underground route graphs, three canal crossings, four approved hero profiles and voice references, 2,400-resident planning baseline, public access and independent inner defense.'),
 ('What remains to develop','The other household interiors, complete occupancy census, final civilian model sheets and voices, detailed founding chronology, companion meetings, migrations, factions, named villains, monsters and exterior regions.'),
 ('Source of authority','Latest owner instructions come first. Current canon and measured plans control the world; event records control changes. This volume adds present-day detail and records future questions. The atmosphere painting is not a measured camera plate.'),
 ('Use across media','The edition supplies stable addresses and relationships for comics, videos, episodes, seasons and game scenes. It is world development material; it does not claim those media have already been produced.')])

def build():
 D=copy.deepcopy(BASE)
 D.update(version='2.1.0',volume='03 / The Living Burrow',date='2026-10-20',status='Present-day development complete for this edition; origins and wider-world history explicitly reserved for the next phase.')
 parents={x['id']:x for x in D['locations']}
 for s in SUBPLANS:
  p=parents[s['parent']];cx,cy=s['center_local_m'];x,y,z=p['position_m'];w,h=s['size_m']
  s['position_m']=[x+cx,y+cy,z];s['footprint_m']=[w,h]
  s['portal']={'side':'S','position_m':[x+cx,y+cy-h/2,z],'width_m':s['door_width_m'],'connects_to':s['parent'],'access':'private household threshold' if s['kind']=='home' else 'supervised care threshold' if s['kind']=='care' else 'ordinary internal doorway'}
  s['status']='authored current spatial canon / v2.1.0';s['blueprint']='blueprints/'+s['id']+'.svg'
 D['sub_locations']=SUBPLANS
 D['present_day']={'neighborhoods':NEIGHBORHOODS,'residents':RESIDENTS,'editorial_rules':{'founder':'Madger created/founded the Burrow, as established by the owner. Motivation, dates, prior site condition and collaborators remain unassigned.','history':'No birthplace, arrival date, companion first meeting, former war, ancient civilization or founding motivation is invented here.','story_seeds':'Possible future stories, not recorded historical events.','new_character_designs':'Civilian species and present roles are authored additions. Visual notes are development specifications; no approved model sheets or voices exist for these residents.','population':'Neighborhood totals retain the v2 planning baseline, not a completed census. H001 is included within UG-04\'s 100-home allocation.','atmosphere':'Underhall painting depicts mood and materials with anonymous neighbors. It does not approve named character likenesses or override measurements.'},'chapters':PAGES}
 D['history_reservations']={'status':'Next phase requested by owner; questions are not canon answers.','subjects':['Madger founding motive and founding sequence','Burrow pre-settlement geography and construction phases','Residents origins and migration routes','First meetings and trust between the four companions','Histories of individual places and present institutions','Antagonist biographies, factions and conflicts','Safe and dangerous regions','Monster and animal ecology, behavior and any supernatural rules'],'event_schema':['event_id','relative_sequence','date_if_established','prerequisites','place_id','participants','objective_event','witness_accounts','rumors','before','after','who_knows','physical_evidence','later_reveal','canon_version']}
 # Correct one stale descriptive phrase without changing the access state established in v2.
 next(x for x in D['locations'] if x['id']=='BRW-13')['role']='An internal handoff space between East Bridge and the public gate vestibule.'
 D['provenance']['new_in_this_edition']=['Five neighborhood identities and eight recurring resident dossiers.','Seven measured sub-locations inside existing allocated rooms.','Present-day civic life, routines, culture and bounded story possibilities.','Owner establishes Madger as founder; reasons and historical sequence remain reserved.','BRW-13 role wording aligned with the already established public daytime gate state.']
 D['change_log'].append({'version':'2.1.0','date':'2026-10-20','reason':'Owner requested continued world development before a later detailed history of places, heroes, antagonists and creatures.','preserved':'All primary geography, route graphs, population plan, hero designs, approved voices and v2 defensive states.','new':'Present-day social world, seven sub-plans and explicit history reservations.'})
 D['document_reference']={'current_edition':'v2.1.0/MADGER_World_Bible.json','living_world':'v2.1.0/MADGER_Living_World.pdf','underground_blueprints':'v2.0.0/MADGER_Underground_Blueprints.pdf','surface_geometry_reference':'blueprints/v1.0.0/MADGER_Burrow_Blueprints.pdf','precedence':'v2.1.0 adds present-day detail; v2.0.0 access and population changes continue to supersede conflicting v1 text.'}
 checks={'all_37_primary_footprints_preserved':all(a['position_m']==b['position_m'] and a['footprint_m']==b['footprint_m'] for a,b in zip(D['locations'],BASE['locations'])) and len(D['locations'])==37,'route_graphs_preserved':D['routes']==BASE['routes'] and D['underground']['routes']==BASE['underground']['routes'],'water_and_crossings_preserved':D['water']==BASE['water'] and D['crossings']==BASE['crossings'],'heroes_and_voices_preserved':D['heroes']==BASE['heroes'] and D['voice_reference']==BASE['voice_reference'],'population_preserved':sum(n['residents'] for n in NEIGHBORHOODS)==2400 and D['geography']['population_plan']==BASE['geography']['population_plan'],'subplans_within_parent_footprints':True,'subplans_nonoverlap':True,'new_ids_unique':len({s['id'] for s in SUBPLANS})==7,'resident_ids_unique':len({r['id'] for r in RESIDENTS})==8}
 for s in SUBPLANS:
  p=parents[s['parent']];x,y=s['center_local_m'];w,h=s['size_m'];pw,ph=p['footprint_m']
  checks['subplans_within_parent_footprints'] &= abs(x)+w/2<=pw/2 and abs(y)+h/2<=ph/2
 for i,a in enumerate(SUBPLANS):
  for b in SUBPLANS[i+1:]:
   if a['parent']!=b['parent']:continue
   ax,ay=a['center_local_m'];bx,by=b['center_local_m'];aw,ah=a['size_m'];bw,bh=b['size_m']
   checks['subplans_nonoverlap'] &= not (abs(ax-bx)<(aw+bw)/2 and abs(ay-by)<(ah+bh)/2)
 ids=set(parents)|{s['id'] for s in SUBPLANS}
 allocated={'UG-03-S01':[-43,22,-27,33],'UG-03-S02':[-23,22,-7,33],'UG-03-S03':[4,22,20,33],'UG-03-S04':[24,22,40,33],'UG-06-R01':[-44,6,-24,26],'UG-07-R01':[-44,6,-32,26],'UG-04-H001':[-44,4,-36,10]}
 checks['subplans_match_v2_room_allocations']=all([s['center_local_m'][0]-s['size_m'][0]/2,s['center_local_m'][1]-s['size_m'][1]/2,s['center_local_m'][0]+s['size_m'][0]/2,s['center_local_m'][1]+s['size_m'][1]/2]==allocated[s['id']] for s in SUBPLANS)
 checks['door_widths_fit_south_walls']=all(0<s['door_width_m']<s['size_m'][0] for s in SUBPLANS)
 checks['resident_location_references_valid']=all(r['home'] in ids and all(x in ids for x in r['work']) for r in RESIDENTS)
 assert all(checks.values()),checks
 D['validation']={'status':'passed','checks':checks,'limits':['Sub-plans are fictional production layouts, not construction engineering.','Only one of the 400 allocated underground homes has an internal plan in this edition.','New resident model sheets, voices and historical biographies are not yet established.']}
 for fn,data in [('MADGER_World_Bible.json',D),('MADGER_Living_World_Data.json',D['present_day']),('Sub_Locations.json',SUBPLANS),('validation.json',D['validation'])]:
  (OUT/fn).write_text(json.dumps(data,indent=2)+'\n')
 return D
if __name__=='__main__':
 D=build();print(json.dumps({'canon':D['version'],'primary_areas':len(D['locations']),'subplans':len(SUBPLANS),'resident_dossiers':len(RESIDENTS),'chapters':len(PAGES),'checks':D['validation']['checks']},indent=2))
